// ساخته‌شده به‌صورت خودکار از dual-diagnosis-protocol (سایت استاتیک) توسط
// tools در جلسه‌ی یکپارچه‌سازی — برای بازتولید: بخش Addendum گزارش دیباگ.
// صفحه شامل CSS درون‌خطی + ویجت گفت‌وگوی فارسی (API نسبی /api/chat) است.
export const PROTOCOL_HTML = "<!DOCTYPE html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>پروتکل تشخیص دوگانه | Dual Diagnosis Protocol</title>\n<meta name=\"description\" content=\"پروتکل درمان تشخیص دوگانه برای ایران — سایکوز + اعتیاد + BPD ± ADHD. مبتنی بر شواهد علمی NICE · APA · WFSBP.\" />\n<meta property=\"og:title\" content=\"پروتکل درمان تشخیص دوگانه برای ایران\" />\n<meta property=\"og:description\" content=\"چارچوب جامع درمان تشخیص دوگانه (سایکوز + اعتیاد + BPD ± ADHD) — از بحران تا بهبودی. مبتنی بر شواهد NICE · APA · WFSBP.\" />\n<meta property=\"og:type\" content=\"website\" />\n<meta name=\"twitter:card\" content=\"summary\" />\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Ctext y='.9em' font-size='90'%3E%E2%9A%95%3C/text%3E%3C/svg%3E\" />\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n<!-- فونت وب به‌صورت غیرمسدودکننده بارگذاری می‌شود؛ اگر گوگل‌فونت در دسترس نباشد\n     (رایج در ایران) صفحه بلافاصله با Tahoma نمایش داده می‌شود و منتظر نمی‌ماند. -->\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\" media=\"print\" onload=\"this.media='all'\" />\n<noscript><link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\" /></noscript>\n<style>\n/* =========================================================\n   پروتکل تشخیص دوگانه — استایل اصلی\n   طراحی: تم پزشکی، راست‌چین، فارسی\n   ========================================================= */\n\n:root {\n  --teal-900: #0b3d3d;\n  --teal-700: #0e6a6a;\n  --teal-600: #0f7c7c;\n  --teal-50: #ecf6f6;\n  --cyan-700: #0e7490;\n  --emerald: #0d9488;\n  --amber: #d97706;\n  --rose: #be123c;\n  --ink: #0f2a2a;\n  --body: #1d2b2b;\n  --muted: #5b7171;\n  --line: #d8e6e6;\n  --bg: #f4f8f8;\n  --bg-alt: #eef4f4;\n  --card: #ffffff;\n  --shadow: 0 1px 2px rgba(11,61,61,.05), 0 8px 24px rgba(11,61,61,.07);\n  --radius: 16px;\n}\n\n* { box-sizing: border-box; margin: 0; padding: 0; }\n\nhtml { scroll-behavior: smooth; }\n\nbody {\n  font-family: 'Vazirmatn', 'Tahoma', 'Segoe UI', sans-serif;\n  background: var(--bg);\n  color: var(--body);\n  line-height: 1.85;\n  font-size: 16px;\n  -webkit-font-smoothing: antialiased;\n}\n\n.container { width: 100%; max-width: 1140px; margin: 0 auto; padding: 0 20px; }\n\na { color: var(--teal-700); text-decoration: none; }\na:hover { text-decoration: underline; }\n\n/* ---------- NAV ---------- */\n.site-nav {\n  position: sticky; top: 0; z-index: 50;\n  background: rgba(255,255,255,.9);\n  backdrop-filter: blur(10px);\n  border-bottom: 1px solid var(--line);\n}\n.nav-inner { display: flex; align-items: center; justify-content: space-between; height: 64px; }\n.brand { display: flex; align-items: center; gap: 10px; font-weight: 800; color: var(--teal-900); font-size: 1.05rem; }\n.brand-mark { width: 34px; height: 34px; display: grid; place-items: center; background: var(--teal-700); color: #fff; border-radius: 10px; font-size: 1.1rem; }\n.nav-links { display: flex; gap: 18px; align-items: center; }\n.nav-links a { color: var(--body); font-size: .92rem; font-weight: 500; }\n.nav-links a:hover { color: var(--teal-700); text-decoration: none; }\n.nav-cta { background: var(--teal-700); color: #fff !important; padding: 7px 16px; border-radius: 999px; }\n.nav-cta:hover { background: var(--teal-900); }\n@media (max-width: 860px) { .nav-links { display: none; } }\n\n/* ---------- HERO ---------- */\n.hero {\n  position: relative; overflow: hidden;\n  background: radial-gradient(1200px 500px at 80% -10%, rgba(13,148,136,.18), transparent 60%),\n              linear-gradient(160deg, #062e2e 0%, #0e6a6a 60%, #0d9488 120%);\n  color: #eafaf8; padding: 84px 0 64px; text-align: center;\n}\n.eyebrow {\n  display: inline-block; padding: 6px 16px; border: 1px solid rgba(255,255,255,.3);\n  border-radius: 999px; font-size: .82rem; color: #bdf0ea; margin-bottom: 22px;\n}\n.hero h1 { font-size: clamp(1.9rem, 4.5vw, 3.1rem); font-weight: 800; line-height: 1.3; letter-spacing: -.5px; }\n.for-iran { color: #7fe3d6; }\n.hero-sub { margin-top: 14px; font-size: 1.12rem; font-weight: 600; color: #d8f5f0; }\n.hero-desc { margin-top: 8px; color: #b9e8e2; font-size: 1rem; }\n.hero-cta { margin-top: 28px; display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }\n.btn {\n  display: inline-block; padding: 12px 26px; border-radius: 999px; font-weight: 700;\n  font-size: .98rem; cursor: pointer; border: none; transition: transform .15s ease, box-shadow .15s ease;\n}\n.btn:hover { text-decoration: none; transform: translateY(-2px); }\n.btn-primary { background: #fff; color: var(--teal-900); box-shadow: 0 8px 24px rgba(0,0,0,.18); }\n.btn-ghost { background: rgba(255,255,255,.1); color: #fff; border: 1px solid rgba(255,255,255,.4); }\n.hero-stats { margin-top: 46px; display: grid; grid-template-columns: repeat(4,1fr); gap: 16px; max-width: 720px; margin-inline: auto; }\n.stat { background: rgba(255,255,255,.08); border: 1px solid rgba(255,255,255,.16); border-radius: 14px; padding: 18px 10px; }\n.stat-num { font-size: 1.9rem; font-weight: 800; color: #7fe3d6; }\n.stat-label { font-size: .82rem; color: #cdeee9; }\n@media (max-width: 600px) { .hero-stats { grid-template-columns: repeat(2,1fr); } }\n\n/* ---------- SECTIONS ---------- */\n.section { padding: 72px 0; }\n.section-alt { background: var(--bg-alt); }\n.section-head { text-align: center; max-width: 760px; margin: 0 auto 44px; }\n.section-kicker { display: inline-block; color: var(--emerald); font-weight: 700; font-size: .85rem; letter-spacing: 1px; margin-bottom: 10px; }\n.section-head h2 { font-size: clamp(1.6rem, 3.5vw, 2.3rem); color: var(--teal-900); font-weight: 800; }\n.section-sub { margin-top: 12px; color: var(--muted); font-size: 1.02rem; }\n\n.sub-block { margin-top: 52px; }\n.sub-title { font-size: 1.3rem; color: var(--teal-900); margin-bottom: 22px; padding-right: 14px; border-right: 4px solid var(--emerald); }\n.muted { color: var(--muted); font-weight: 500; font-size: .9rem; }\n\n/* ---------- GRID ---------- */\n.cards-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 20px; }\n.cards-grid-4 { grid-template-columns: repeat(4,1fr); }\n.cards-grid-3 { grid-template-columns: repeat(3,1fr); }\n@media (max-width: 900px) { .cards-grid, .cards-grid-3 { grid-template-columns: repeat(2,1fr); } .cards-grid-4 { grid-template-columns: repeat(2,1fr); } }\n@media (max-width: 600px) { .cards-grid, .cards-grid-3, .cards-grid-4 { grid-template-columns: 1fr; } }\n\n/* ---------- MODEL CARDS ---------- */\n.model-card { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 22px; box-shadow: var(--shadow); }\n.model-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.model-head h3 { font-size: 1.08rem; color: var(--teal-900); }\n.model-en { color: var(--muted); font-size: .85rem; font-weight: 500; }\n.model-card p { font-size: .93rem; margin-bottom: 10px; color: var(--body); }\n.mech, .use { font-size: .86rem; color: #41584f; background: var(--teal-50); padding: 10px 12px; border-radius: 10px; }\n.use { background: #f0fdf9; }\n\n.badge { font-size: .72rem; font-weight: 700; padding: 4px 10px; border-radius: 999px; white-space: nowrap; }\n.badge-strong { background: #dcfce7; color: #166534; }\n.badge-good { background: #dbeafe; color: #1e40af; }\n.badge-weak { background: #fef3c7; color: #92400e; }\n.badge-emerging { background: #f3e8ff; color: #6b21a8; }\n\n/* ---------- CHIPS ---------- */\n.chips { display: flex; flex-wrap: wrap; gap: 10px; }\n.chip { background: var(--card); border: 1px solid var(--line); padding: 8px 16px; border-radius: 999px; font-size: .88rem; color: var(--teal-900); font-weight: 500; }\n\n/* ---------- FINDINGS ---------- */\n.finding { background: var(--card); border-top: 3px solid var(--emerald); border-radius: 12px; padding: 18px; box-shadow: var(--shadow); }\n.finding h4 { color: var(--teal-900); font-size: .98rem; margin-bottom: 8px; }\n.finding p { font-size: .86rem; color: var(--muted); }\n\n/* ---------- GUIDELINE CARDS ---------- */\n.gl-card { background: var(--card); border-radius: var(--radius); padding: 22px; box-shadow: var(--shadow); border: 1px solid var(--line); position: relative; }\n.gl-year { font-size: .76rem; font-weight: 700; color: var(--emerald); background: #ecfdf5; padding: 4px 10px; border-radius: 999px; display: inline-block; margin-bottom: 12px; }\n.gl-card h3 { color: var(--teal-900); font-size: 1.15rem; }\n.gl-sub { color: var(--muted); font-size: .85rem; margin-bottom: 14px; }\n.gl-card ul { list-style: none; }\n.gl-card ul li { font-size: .88rem; padding: 6px 0 6px 22px; position: relative; border-top: 1px dashed var(--line); color: var(--body); }\n.gl-card ul li:first-child { border-top: none; }\n.gl-card ul li::before { content: \"✓\"; position: absolute; right: 0; color: var(--emerald); font-weight: 700; }\n\n/* ---------- PRINCIPLES ---------- */\n.principle { background: var(--card); border-radius: var(--radius); padding: 22px; text-align: center; box-shadow: var(--shadow); border: 1px solid var(--line); }\n.p-emoji { font-size: 2rem; margin-bottom: 8px; }\n.principle h4 { color: var(--teal-900); font-size: 1rem; margin-bottom: 8px; }\n.principle p { font-size: .86rem; color: var(--muted); }\n\n/* ---------- MEDICATION ALGORITHM ---------- */\n.algo { position: relative; }\n.stage { display: flex; gap: 18px; background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 22px; margin-bottom: 16px; box-shadow: var(--shadow); }\n.stage-num { flex-shrink: 0; width: 46px; height: 46px; border-radius: 14px; background: linear-gradient(135deg, var(--teal-700), var(--emerald)); color: #fff; display: grid; place-items: center; font-size: 1.3rem; font-weight: 800; }\n.stage-body { flex: 1; }\n.stage-body h3 { color: var(--teal-900); font-size: 1.1rem; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }\n.stage-time { font-size: .8rem; font-weight: 600; color: var(--muted); background: var(--bg-alt); padding: 3px 10px; border-radius: 999px; }\n.dual-protocol { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin: 14px 0; }\n.proto { border-radius: 12px; padding: 14px; }\n.proto p { font-size: .88rem; margin-top: 6px; }\n.urban { background: #eef5ff; border: 1px solid #d4e3ff; }\n.rural { background: #fef6ec; border: 1px solid #fde6c8; }\n.proto-tag { font-size: .8rem; font-weight: 700; display: block; }\n.pass { font-size: .86rem; color: #41584f; background: var(--teal-50); padding: 8px 12px; border-radius: 8px; border-right: 3px solid var(--emerald); }\n.warn { color: var(--rose); }\n@media (max-width: 680px) { .dual-protocol { grid-template-columns: 1fr; } .stage { flex-direction: column; } }\n\n.callout { background: linear-gradient(135deg, #fffbeb, #fef3c7); border: 1px solid #fde68a; border-radius: var(--radius); padding: 22px; margin-top: 28px; }\n.callout h4 { color: #92400e; margin-bottom: 12px; }\n.callout ul { list-style: none; }\n.callout ul li { font-size: .9rem; padding: 6px 22px 6px 0; position: relative; }\n.callout ul li::before { content: \"•\"; position: absolute; right: 4px; color: var(--amber); font-weight: 700; }\n.callout-care { background: linear-gradient(135deg, #fdf2f8, #fce7f3); border-color: #fbcfe8; }\n.callout-care h4, .callout-care strong { color: #9d174d; }\n.callout-iran { background: linear-gradient(135deg, #ecfdf5, #d1fae5); border-color: #a7f3d0; }\n.callout-iran h4 { color: #065f46; }\n.callout p { font-size: .92rem; }\n\n/* ---------- PSYCH INTERVENTIONS ---------- */\n.psych { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow); border-top: 3px solid var(--cyan-700); }\n.psych h4 { color: var(--teal-900); font-size: 1rem; margin-bottom: 6px; }\n.psych p { font-size: .86rem; color: var(--muted); margin-bottom: 12px; }\n.meta { font-size: .76rem; color: var(--cyan-700); font-weight: 600; background: #ecfeff; padding: 4px 10px; border-radius: 999px; }\n\n/* ---------- LEVELS ---------- */\n.level-tabs { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 24px; }\n.level-tab { background: var(--card); border: 1px solid var(--line); padding: 10px 18px; border-radius: 999px; font-size: .86rem; font-weight: 600; color: var(--teal-900); }\n.level-detail { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 28px; box-shadow: var(--shadow); }\n.level-detail h3 { color: var(--teal-900); font-size: 1.25rem; }\n.budget { margin: 10px 0 18px; font-size: 1rem; color: var(--amber); font-weight: 600; }\n.blk { color: var(--teal-900); margin: 20px 0 12px; font-size: 1rem; }\n.outcomes { display: flex; flex-wrap: wrap; gap: 10px; }\n.outcome { background: #ecfdf5; border: 1px solid #a7f3d0; padding: 8px 16px; border-radius: 10px; font-size: .88rem; color: #065f46; font-weight: 500; }\n.table-wrap { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; font-size: .86rem; min-width: 620px; }\ntable th { background: var(--teal-700); color: #fff; padding: 12px; text-align: right; font-weight: 600; }\ntable td { padding: 12px; border-bottom: 1px solid var(--line); color: var(--body); }\ntable tr:nth-child(even) td { background: var(--bg-alt); }\n.hidden-costs { display: grid; grid-template-columns: repeat(3,1fr); gap: 14px; margin-top: 6px; }\n.hc { background: #fff1f2; border: 1px solid #fecdd3; border-radius: 12px; padding: 16px; text-align: center; }\n.hc span { font-size: .82rem; color: #9f1239; display: block; margin-bottom: 6px; }\n.hc strong { color: var(--rose); font-size: 1.2rem; }\n@media (max-width: 680px) { .hidden-costs { grid-template-columns: 1fr; } }\n\n.kpi-row { display: grid; grid-template-columns: repeat(4,1fr); gap: 16px; }\n.kpi { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 22px; text-align: center; box-shadow: var(--shadow); }\n.kpi-val { font-size: 2rem; font-weight: 800; color: var(--emerald); }\n.kpi-label { font-size: .84rem; color: var(--muted); margin-top: 4px; }\n@media (max-width: 680px) { .kpi-row { grid-template-columns: repeat(2,1fr); } }\n\n/* ---------- CAREGIVER ---------- */\n.train, .integ { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow); }\n.train { border-top: 3px solid var(--rose); }\n.integ { border-top: 3px solid var(--cyan-700); }\n.t-emoji, .i-emoji { font-size: 1.8rem; margin-bottom: 8px; }\n.train h4, .integ h4 { color: var(--teal-900); font-size: .98rem; margin-bottom: 8px; }\n.train p, .integ p { font-size: .85rem; color: var(--muted); }\n.tool-note { margin-top: 16px; background: var(--teal-50); padding: 12px 16px; border-radius: 10px; font-size: .88rem; color: #41584f; border-right: 3px solid var(--emerald); }\n\n.hr-card { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; box-shadow: var(--shadow); }\n.hr-card h4 { color: var(--teal-900); font-size: .95rem; margin-bottom: 6px; }\n.hr-card p { font-size: .84rem; color: var(--muted); margin-bottom: 10px; }\n\n/* ---------- PATIENT SHEET ---------- */\n.print-btn-row { text-align: center; margin-bottom: 24px; }\n.sheet { background: #fff; border: 2px solid var(--teal-700); border-radius: var(--radius); padding: 34px; box-shadow: var(--shadow); }\n.sheet-title { color: var(--teal-900); font-size: 1.4rem; padding-bottom: 14px; border-bottom: 2px dashed var(--line); margin-bottom: 18px; }\n.sheet h4 { color: var(--teal-900); margin: 18px 0 10px; }\n.sheet-text { font-size: .95rem; background: var(--bg-alt); padding: 14px 16px; border-radius: 10px; }\n.qa { display: grid; gap: 12px; }\n.q { display: flex; gap: 12px; background: var(--bg-alt); padding: 14px; border-radius: 10px; }\n.qn { flex-shrink: 0; width: 28px; height: 28px; border-radius: 50%; background: var(--teal-700); color: #fff; display: grid; place-items: center; font-size: .85rem; font-weight: 700; }\n.q p { font-size: .9rem; }\n.refs-list { list-style: none; }\n.refs-list li { font-size: .88rem; padding: 6px 18px 6px 0; position: relative; color: var(--body); }\n.refs-list li::before { content: \"•\"; position: absolute; right: 2px; color: var(--emerald); }\n.sheet-note { margin-top: 20px; background: #fffbeb; border: 1px solid #fde68a; border-radius: 12px; padding: 16px; }\n.sheet-note p { font-size: .88rem; color: #41584f; }\n\n/* ---------- DECISION TREE ---------- */\n.decision-options { display: flex; gap: 14px; flex-wrap: wrap; }\n.dec-opt { background: var(--card); border: 2px solid var(--line); padding: 14px 26px; border-radius: 12px; font-size: .95rem; font-weight: 600; color: var(--teal-900); cursor: pointer; transition: all .15s; }\n.dec-opt:hover { border-color: var(--emerald); background: #ecfdf5; }\n.tree { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 26px; box-shadow: var(--shadow); }\n.tree-node { background: var(--teal-700); color: #fff; padding: 12px 20px; border-radius: 12px; display: inline-block; font-weight: 600; margin: 8px 0; }\n.tree-branches { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin-top: 12px; }\n.branch { background: var(--bg-alt); border-radius: 12px; padding: 16px; }\n.branch-label { display: inline-block; font-weight: 700; color: var(--teal-900); margin-bottom: 10px; font-size: .9rem; }\n.tree-result { display: inline-block; background: #ecfdf5; color: #065f46; padding: 8px 16px; border-radius: 10px; font-weight: 600; font-size: .9rem; border: 1px solid #a7f3d0; }\n@media (max-width: 680px) { .tree-branches { grid-template-columns: 1fr; } }\n\n/* ---------- TIMELINE ---------- */\n.timeline { display: grid; grid-template-columns: repeat(3,1fr); gap: 22px; }\n.tl-col { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 24px; box-shadow: var(--shadow); }\n.tl-col h3 { color: #fff; background: linear-gradient(135deg, var(--teal-700), var(--emerald)); padding: 8px 16px; border-radius: 10px; font-size: 1.05rem; margin-bottom: 18px; text-align: center; }\n.tl-step { display: flex; gap: 12px; margin-bottom: 16px; }\n.tl-n { flex-shrink: 0; width: 26px; height: 26px; border-radius: 8px; background: var(--teal-50); color: var(--teal-700); display: grid; place-items: center; font-weight: 700; font-size: .82rem; }\n.tl-step h4 { color: var(--teal-900); font-size: .92rem; margin-bottom: 2px; }\n.tl-step p { font-size: .82rem; color: var(--muted); }\n@media (max-width: 880px) { .timeline { grid-template-columns: 1fr; } }\n\n.budget-card { border-radius: var(--radius); padding: 22px; box-shadow: var(--shadow); border: 1px solid var(--line); }\n.b-low { background: #fef6ec; border-color: #fde6c8; }\n.b-mid { background: #eef5ff; border-color: #d4e3ff; }\n.b-high { background: #fffbeb; border-color: #fde68a; }\n.b-tag { font-size: .82rem; font-weight: 700; display: block; margin-bottom: 10px; color: var(--teal-900); }\n.budget-card h4 { color: var(--teal-900); margin-bottom: 8px; }\n.budget-card p { font-size: .86rem; color: var(--muted); }\n\n.contacts { display: grid; grid-template-columns: repeat(4,1fr); gap: 14px; }\n.contact { display: flex; align-items: center; gap: 14px; background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; box-shadow: var(--shadow); }\n.contact:hover { text-decoration: none; border-color: var(--emerald); transform: translateY(-2px); }\n.c-num { font-size: 1.7rem; font-weight: 800; color: var(--emerald); }\n.c-name { font-size: .9rem; font-weight: 600; color: var(--teal-900); line-height: 1.4; }\n.c-name small { color: var(--muted); font-weight: 400; }\n@media (max-width: 760px) { .contacts { grid-template-columns: repeat(2,1fr); } }\n\n/* ---------- REFERENCES ---------- */\n.ref-group { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 22px; box-shadow: var(--shadow); }\n.ref-group > h3 { color: var(--teal-900); font-size: 1.1rem; margin-bottom: 16px; padding-bottom: 10px; border-bottom: 2px solid var(--teal-50); }\n.ref { padding: 12px 0; border-bottom: 1px dashed var(--line); }\n.ref:last-child { border-bottom: none; }\n.ref-year, .ref-type { font-size: .74rem; font-weight: 700; color: var(--cyan-700); display: inline-block; margin-bottom: 6px; }\n.ref h4 { color: var(--teal-900); font-size: .92rem; margin-bottom: 4px; line-height: 1.5; }\n.ref p { font-size: .82rem; color: var(--muted); }\n\n/* ---------- FOOTER ---------- */\n.site-footer { background: var(--teal-900); color: #cdeee9; padding: 40px 0; text-align: center; }\n.site-footer p { margin-bottom: 6px; }\n.site-footer strong { color: #fff; font-size: 1.05rem; }\n.footer-sub { font-size: .88rem; color: #9fd9d2; }\n.footer-warn { margin-top: 14px; font-size: .82rem; color: #ffd9a8; max-width: 620px; margin-inline: auto; }\n\n/* ---------- PRINT ---------- */\n@media print {\n  .site-nav, .hero, .print-btn-row, .site-footer, .section-head, .timeline,\n  #etiology, #guidelines, #meds, #levels, #caregiver, #decision, #action, #references,\n  .sub-block { display: none !important; }\n  body { background: #fff; }\n  #sheet.section, #sheet.section-alt { padding: 0; background: #fff; }\n  .sheet { border-color: #000; box-shadow: none; }\n}\n\n\n/* --- ویجگت گفت‌وگوی دستیار --- */\n#ddx-chat-btn{position:fixed;bottom:18px;left:18px;z-index:9998;background:#0e7c7c;color:#fff;\nborder:none;border-radius:28px;padding:12px 20px;font:inherit;font-size:15px;cursor:pointer;\nbox-shadow:0 6px 18px rgba(14,124,124,.35)}\n#ddx-chat-btn:hover{background:#0a6363}\n#ddx-chat-panel{position:fixed;bottom:74px;left:18px;z-index:9999;width:min(370px,calc(100vw - 36px));\nheight:480px;max-height:70vh;background:#fff;border:1px solid #d8e6e6;border-radius:14px;\nbox-shadow:0 12px 40px rgba(0,0,0,.18);display:none;flex-direction:column;overflow:hidden;\nfont-family:inherit}\n#ddx-chat-panel.open{display:flex}\n#ddx-chat-head{background:#0e7c7c;color:#fff;padding:12px 16px;display:flex;\njustify-content:space-between;align-items:center}\n#ddx-chat-head b{font-size:15px}\n#ddx-chat-close{background:none;border:none;color:#fff;font-size:20px;cursor:pointer;line-height:1}\n#ddx-chat-msgs{flex:1;overflow-y:auto;padding:12px;display:flex;flex-direction:column;gap:8px;\nbackground:#f6fbfb}\n.ddx-msg{max-width:85%;padding:9px 12px;border-radius:12px;font-size:14px;line-height:1.9;\nwhite-space:pre-wrap;word-break:break-word}\n.ddx-msg.user{align-self:flex-start;background:#0e7c7c;color:#fff;border-bottom-right-radius:4px}\n.ddx-msg.bot{align-self:flex-end;background:#fff;border:1px solid #d8e6e6;border-bottom-left-radius:4px}\n#ddx-chat-form{display:flex;border-top:1px solid #d8e6e6;background:#fff}\n#ddx-chat-in{flex:1;border:none;padding:12px;font:inherit;font-size:14px;outline:none}\n#ddx-chat-send{border:none;background:#0e7c7c;color:#fff;padding:0 18px;font:inherit;cursor:pointer}\n#ddx-chat-send:disabled{background:#9cc4c4}\n@media print{#ddx-chat-btn,#ddx-chat-panel{display:none !important}}\n</style>\n</head>\n<body>\n\n<!-- ===================== NAV ===================== -->\n<header class=\"site-nav\">\n  <div class=\"container nav-inner\">\n    <div class=\"brand\">\n      <span class=\"brand-mark\">⚕</span>\n      <span>پروتکل تشخیص دوگانه</span>\n    </div>\n    <nav class=\"nav-links\">\n      <a href=\"#etiology\">اتیولوژی</a>\n      <a href=\"#guidelines\">راهنماها</a>\n      <a href=\"#meds\">دارو</a>\n      <a href=\"#levels\">سطوح درمان</a>\n      <a href=\"#caregiver\">همراه</a>\n      <a href=\"#sheet\">برگه پزشک</a>\n      <a href=\"#references\" class=\"nav-cta\">منابع</a>\n    </nav>\n  </div>\n</header>\n\n<!-- ===================== HERO ===================== -->\n<section class=\"hero\">\n  <div class=\"container\">\n    <div class=\"eyebrow\">مبتنی بر شواهد علمی — NICE · APA · WFSBP</div>\n    <h1>پروتکل درمان تشخیص دوگانه <span class=\"for-iran\">برای ایران</span></h1>\n    <p class=\"hero-sub\">سایکوز / اسکیزوفرنی + اختلال مصرف مواد + BPD ± ADHD</p>\n    <p class=\"hero-desc\">چارچوب جامع، واقع‌گرایانه و خانواده‌محور — از بحران تا بهبودی</p>\n    <div class=\"hero-cta\">\n      <a href=\"#sheet\" class=\"btn btn-primary\">برگه پزشک (فوری)</a>\n      <a href=\"#meds\" class=\"btn btn-ghost\">الگوریتم دارویی</a>\n    </div>\n    <div class=\"hero-stats\">\n      <div class=\"stat\"><div class=\"stat-num\">۵</div><div class=\"stat-label\">مدل اتیولوژیکی</div></div>\n      <div class=\"stat\"><div class=\"stat-num\">۶+</div><div class=\"stat-label\">راهنمای بالینی</div></div>\n      <div class=\"stat\"><div class=\"stat-num\">۴</div><div class=\"stat-label\">سطح درمانی</div></div>\n      <div class=\"stat\"><div class=\"stat-num\">∞</div><div class=\"stat-label\">امیدواری</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ===================== ETIOLOGY ===================== -->\n<section id=\"etiology\" class=\"section\">\n  <div class=\"container\">\n    <div class=\"section-head\">\n      <span class=\"section-kicker\">علت‌شناسی و مکانیسم‌ها</span>\n      <h2>اتیوپاتوژنز</h2>\n      <p class=\"section-sub\">مدل‌های اصلی علتی تشخیص دوگانه — بر اساس مرورهای کلاسیک و مقالات جدید (۲۰۲۳-۲۰۲۴)</p>\n    </div>\n\n    <div class=\"cards-grid\">\n      <article class=\"model-card\">\n        <div class=\"model-head\">\n          <h3>مدل عوامل مشترک <span class=\"model-en\">(Common Factor)</span></h3>\n          <span class=\"badge badge-strong\">قوی</span>\n        </div>\n        <p>آسیب‌پذیری مشترک ژنتیکی، تروماهای کودکی، اختلال دلبستگی، تکانشگری و نقص در تنظیم هیجان.</p>\n        <p class=\"mech\"><strong>مکانیسم:</strong> پلی‌مورفیسم‌های DRD2 و COMT، ACE (تجربیات نامطلوب کودکی)، و اختلال در مسیرهای تنظیم هیجانی قشر پیش‌پیشانی-آمیگدالا.</p>\n        <p class=\"use\"><strong>کاربرد درمانی:</strong> DBT برای تنظیم هیجان + خانواده‌درمانی برای ترمیم دلبستگی.</p>\n      </article>\n\n      <article class=\"model-card\">\n        <div class=\"model-head\">\n          <h3>مدل فوق‌حساسیت <span class=\"model-en\">(Supersensitivity)</span></h3>\n          <span class=\"badge badge-good\">خوب</span>\n        </div>\n        <p>آسیب‌پذیری زیستی مغز (سیستم دوپامین مزولیمبیک) باعث می‌شود مقادیر کم ماده، علائم شدیدتری ایجاد کند.</p>\n        <p class=\"mech\"><strong>مکانیسم:</strong> افزایش حساسیت گیرنده‌های D2 در مسیر مزولیمبیک به دلیل مصرف مزمن مواد → نیازمندی کمتر برای فعال‌سازی سایکوز.</p>\n        <p class=\"use\"><strong>کاربرد درمانی:</strong> کلوزاپین (آنتاگونیست D2 ضعیف‌تر) به جای ریسپریدون/اولانزاپین.</p>\n      </article>\n\n      <article class=\"model-card\">\n        <div class=\"model-head\">\n          <h3>مدل خوددرمانی <span class=\"model-en\">(Self-medication)</span></h3>\n          <span class=\"badge badge-weak\">ضعیف تا متوسط</span>\n        </div>\n        <p>بیمار برای کاهش علائم منفی یا اضطراب مواد مصرف می‌کند.</p>\n        <p class=\"mech\"><strong>مکانیسم:</strong> بیمار سعی می‌کند با مصرف مواد، علائم منفی سایکوز (آمیواسیون، آنهدونیا) یا اضطراب را کاهش دهد.</p>\n        <p class=\"use\"><strong>کاربرد درمانی:</strong> مصاحبه انگیزشی (MI) + CBT برای شناسایی الگوی مصرف.</p>\n      </article>\n\n      <article class=\"model-card\">\n        <div class=\"model-head\">\n          <h3>مدل دوسویه <span class=\"model-en\">(Bidirectional)</span></h3>\n          <span class=\"badge badge-strong\">قوی</span>\n        </div>\n        <p>هر دو اختلال یکدیگر را تشدید می‌کنند (مواد → تشدید سایکوز؛ سایکوز → افزایش مصرف).</p>\n        <p class=\"mech\"><strong>مکانیسم:</strong> حلقه بازخورد مثبت: مواد → تشدید دوپامین → تشدید سایکوز → افزایش اضطراب → افزایش مصرف.</p>\n        <p class=\"use\"><strong>کاربرد درمانی:</strong> درمان یکپارچه (همزمان روان‌پریشی و اعتیاد).</p>\n      </article>\n\n      <article class=\"model-card\">\n        <div class=\"model-head\">\n          <h3>مدل آسیب عصبی مشترک <span class=\"model-en\">(Shared Neurotoxicity)</span></h3>\n          <span class=\"badge badge-emerging\">در حال گسترش</span>\n        </div>\n        <p>اختلال در مدار پاداش (Nucleus Accumbens)، محور HPA، التهاب عصبی و نقص کارکرد اجرایی.</p>\n        <p class=\"mech\"><strong>مکانیسم:</strong> افزایش سایتوکاین‌های التهابی (IL-6، TNF-α) → اختلال مدار پاداش و قشر پیش‌پیشانی → نقص اجرایی مشترک ADHD و سایکوز.</p>\n        <p class=\"use\"><strong>کاربرد درمانی:</strong> داروهای ضدالتهاب (مینوسیکلین کارآزمایی) + رژیم ضدالتهاب + CRT.</p>\n      </article>\n    </div>\n\n    <div class=\"sub-block\">\n      <h3 class=\"sub-title\">عوامل خطر کلیدی در BPD + سایکوز + اعتیاد</h3>\n      <div class=\"chips\">\n        <span class=\"chip\">ترومای کودکی (ACE)</span>\n        <span class=\"chip\">بی‌ثباتی هویت</span>\n        <span class=\"chip\">تکانشگری</span>\n        <span class=\"chip\">اختلال تنظیم هیجان</span>\n        <span class=\"chip\">مصرف حشیش در سنین پایین (خطر ۴ برابری)</span>\n        <span class=\"chip\">محرک‌ها (کوکائین/آمفتامین)</span>\n        <span class=\"chip\">اختلال دلبستگی</span>\n        <span class=\"chip\">نقص کارکرد اجرایی</span>\n      </div>\n    </div>\n\n    <div class=\"sub-block\">\n      <h3 class=\"sub-title\">یافته‌های جدید (۲۰۲۳-۲۰۲۴)</h3>\n      <div class=\"cards-grid cards-grid-4\">\n        <div class=\"finding\">\n          <h4>مصرف حشیش در نوجوانی</h4>\n          <p>خطر ۴ برابری برای سایکوز در بزرگسالی (مطالعه کوهورت ۲۰۲۳). اثر دوز-واکنش مستند.</p>\n        </div>\n        <div class=\"finding\">\n          <h4>ترومای بین‌فردی</h4>\n          <p>همپوشانی قوی با BPD و سایکوز (مطالعه WADD-SEPD ۲۰۲۴). نقش مرکزی در هر دو اختلال.</p>\n        </div>\n        <div class=\"finding\">\n          <h4>نقص کارکرد اجرایی</h4>\n          <p>هم در ADHD و هم در سایکوز → نیاز به توانبخشی شناختی (CRT) به‌عنوان مداخله مشترک.</p>\n        </div>\n        <div class=\"finding\">\n          <h4>التهاب عصبی</h4>\n          <p>افزایش IL-6 و TNF-α در مصرف مزمن مواد و سایکوز → اختلال مدار پاداش و قشر پیش‌پیشانی.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ===================== GUIDELINES ===================== -->\n<section id=\"guidelines\" class=\"section section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head\">\n      <span class=\"section-kicker\">Evidence-Based Guidelines</span>\n      <h2>راهنماهای مبتنی بر شواهد</h2>\n      <p class=\"section-sub\">پروتکل‌های معتبر بین‌المللی برای درمان تشخیص دوگانه</p>\n    </div>\n\n    <div class=\"cards-grid cards-grid-3\">\n      <div class=\"gl-card\"><span class=\"gl-year\">۲۰۱۱ (+ به‌روزرسانی)</span><h3>NICE CG120</h3><p class=\"gl-sub\">Psychosis with coexisting substance misuse</p><ul><li>درمان یکپارچه (Integrated) برای سایکوز + سوءمصرف مواد</li><li>ارزیابی روتین مصرف مواد در همه بیماران سایکوز</li><li>عدم محروم کردن بیمار از درمان به دلیل تشخیص دوگانه</li></ul></div>\n      <div class=\"gl-card\"><span class=\"gl-year\">۲۰۱۶</span><h3>NICE NG58</h3><p class=\"gl-sub\">Coexisting severe mental illness and substance misuse</p><ul><li>خدمات اجتماعی و هماهنگی بین‌سازمانی</li><li>برنامه‌های مدیریت پرونده (Case Management)</li><li>پوشش خدمات برای بیماری شدید روانی + سوءمصرف</li></ul></div>\n      <div class=\"gl-card\"><span class=\"gl-year\">۲۰۲۰</span><h3>APA Practice Guideline</h3><p class=\"gl-sub\">Schizophrenia (2020)</p><ul><li>ارزیابی مصرف مواد در ارزیابی اولیه</li><li>کلوزاپین در موارد مقاوم به درمان یا خطر خودکشی بالا</li><li>تأکید بر درمان یکپارچه و نه متوالی</li></ul></div>\n      <div class=\"gl-card\"><span class=\"gl-year\">۲۰۱۵-۲۰۲۳</span><h3>WFSBP Guidelines</h3><p class=\"gl-sub\">Hasan et al. (2015/2023)</p><ul><li>کلوزاپین برای اسکیزوفرنی + وابستگی به الکل (شواهد سطح B)</li><li>مداخلات روانی-اجتماعی با مؤلفه انگیزشی و رفتاری</li><li>توصیه‌های اختصاصی بر اساس نوع ماده</li></ul></div>\n      <div class=\"gl-card\"><span class=\"gl-year\">۲۰۲۳</span><h3>Canadian Guidelines</h3><p class=\"gl-sub\">Schizophrenia Guidelines</p><ul><li>درمان یکپارچه در برنامه‌های Early Intervention</li><li>ترکیب دارو + مداخلات اعتیاد</li><li>توانبخشی شناختی (CRT) برای نقص اجرایی</li></ul></div>\n      <div class=\"gl-card\"><span class=\"gl-year\">۲۰۲۱-۲۰۲۲</span><h3>راهنمای اسپانیایی</h3><p class=\"gl-sub\">Arranz et al.</p><ul><li>توصیه‌های اختصاصی بر اساس نوع ماده</li><li>حشیش، کوکائین، الکل، نیکوتین — رویکرد جداگانه</li><li>مداخلات تنظیم‌شده بر پروفایل مصرف</li></ul></div>\n    </div>\n\n    <div class=\"sub-block\">\n      <h3 class=\"sub-title\">اصول مشترک همه راهنماها</h3>\n      <div class=\"cards-grid cards-grid-3\">\n        <div class=\"principle\"><div class=\"p-emoji\">🔄</div><h4>درمان یکپارچه</h4><p>Integrated Treatment بهتر از درمان موازی یا متوالی است. هر دو اختلال باید همزمان درمان شوند.</p></div>\n        <div class=\"principle\"><div class=\"p-emoji\">💊</div><h4>اولویت: تثبیت دارویی + MI + CBT</h4><p>مصاحبه انگیزشی (MI) + CBT برای سایکوز + پیشگیری از عود. تثبیت دارویی پیش‌شرط مداخلات روانی است.</p></div>\n        <div class=\"principle\"><div class=\"p-emoji\">⚡</div><h4>کلوزاپین: قوی‌ترین سیگنال</h4><p>برای کاهش مصرف مواد (به‌ویژه الکل) در اسکیزوفرنی. نیاز به نظارت دقیق CBC (آگرانولوسیتوزیس).</p></div>\n        <div class=\"principle\"><div class=\"p-emoji\">💉</div><h4>تزریق طولانی‌اثر (LAI)</h4><p>برای افزایش پایبندی. ریسپریدون LAI یا پالی‌پریدون پالمیتات (تزریق ماهانه).</p></div>\n        <div class=\"principle\"><div class=\"p-emoji\">👨‍👩‍👦</div><h4>خانواده‌درمانی + مدیریت پرونده</h4><p>Case Management حیاتی است. آموزش خانواده و درگیری آنها در تیم درمانی.</p></div>\n        <div class=\"principle\"><div class=\"p-emoji\">🛡️</div><h4>کاهش آسیب (Harm Reduction)</h4><p>در صورت لغزش، پذیرفته است. هدف مطلق: پرهیز کامل. هدف واقع‌گرایانه: کاهش مصرف و آسیب.</p></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ===================== MEDICATION ===================== -->\n<section id=\"meds\" class=\"section\">\n  <div class=\"container\">\n    <div class=\"section-head\">\n      <span class=\"section-kicker\">Gold Standard</span>\n      <h2>الگوریتم دارویی تطبیقی</h2>\n      <p class=\"section-sub\">پروتکل شهری و روستایی — بر اساس NICE CG120 و APA 2020 و WFSBP</p>\n    </div>\n\n    <div class=\"algo\">\n      <div class=\"stage\">\n        <div class=\"stage-num\">۱</div>\n        <div class=\"stage-body\">\n          <h3>تثبیت حاد <span class=\"stage-time\">هفته ۱-۲</span></h3>\n          <div class=\"dual-protocol\">\n            <div class=\"proto urban\"><span class=\"proto-tag\">🏥 پروتکل شهری</span><p>اولانزاپین ۱۰mg شروع → افزایش تا ۲۰mg / والپروات ۵۰۰mg BD</p></div>\n            <div class=\"proto rural\"><span class=\"proto-tag\">🏘️ پروتکل روستایی / همراه-محور</span><p>اولانزاپین خوراکی یا تزریقی کوتاه‌اثر / والپروات با کنترل کبدی محدود</p></div>\n          </div>\n          <p class=\"pass\"><strong>معیار عبور:</strong> اگر PANSS &gt;۶۰ یا YMRS &gt;۲۰ پس از ۷ روز → مرحله ۲</p>\n        </div>\n      </div>\n\n      <div class=\"stage\">\n        <div class=\"stage-num\">۲</div>\n        <div class=\"stage-body\">\n          <h3>سایکوز مقاوم <span class=\"stage-time\">هفته ۳-۱۸</span> <span class=\"badge badge-strong\">نیاز به نظارت سخت</span></h3>\n          <div class=\"dual-protocol\">\n            <div class=\"proto urban\"><span class=\"proto-tag\">🏥 پروتکل شهری</span><p>شروع ۱۲.۵mg → افزایش تدریجی تا ۳۰۰-۴۰۰mg / CBC هفتگی برای ۱۸ هفته</p></div>\n            <div class=\"proto rural\"><span class=\"proto-tag\">🏘️ پروتکل روستایی / همراه-محور</span><p>جایگزین: ریسپریدون LAI یا پالی‌پریدون پالمیتات (تزریق ماهانه)</p></div>\n          </div>\n          <p class=\"pass\"><strong>معیار عبور:</strong> در سطح ۴: آزمایش CBC ماهانه یا با آزمایشگاه سیار</p>\n        </div>\n      </div>\n\n      <div class=\"stage\">\n        <div class=\"stage-num\">۳</div>\n        <div class=\"stage-body\">\n          <h3>تثبیت‌کننده خلق <span class=\"stage-time\">ماه ۲ تا مادام‌العمر</span></h3>\n          <div class=\"dual-protocol\">\n            <div class=\"proto urban\"><span class=\"proto-tag\">🏥 پروتکل شهری</span><p>لیتیوم: سطح خونی ۰.۸-۱.۲ mEq/L / والپروات: کنترل کبدی</p></div>\n            <div class=\"proto rural\"><span class=\"proto-tag\">🏘️ پروتکل روستایی / همراه-محور</span><p>والپروات ترجیحی (کنترل کمتر حساس) / هر ۳ ماه کنترل تیروئید و کلیه</p></div>\n          </div>\n          <p class=\"pass\"><strong>معیار عبور:</strong> اگر eGFR &lt; ۶۰ → والپروات ترجیح</p>\n        </div>\n      </div>\n\n      <div class=\"stage\">\n        <div class=\"stage-num\">۴</div>\n        <div class=\"stage-body\">\n          <h3>ADHD <span class=\"stage-time\">ماه ۴ به بعد</span></h3>\n          <div class=\"dual-protocol\">\n            <div class=\"proto urban\"><span class=\"proto-tag\">🏥 پروتکل شهری</span><p>شروع ۲۵mg → افزایش تا ۸۰mg / کنترل فشار خون در ماه اول</p></div>\n            <div class=\"proto rural\"><span class=\"proto-tag\">🏘️ پروتکل روستایی / همراه-محور</span><p>همان پروتکل، با نظارت همراه / <strong class=\"warn\">ممنوع:</strong> محرک‌ها (ریتالین/آدرال)</p></div>\n          </div>\n          <p class=\"pass\"><strong>معیار عبور:</strong> تنها پس از تثبیت سایکوز و خلق</p>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"callout\">\n      <h4>قبل از شروع کلوزاپین / والپروات:</h4>\n      <ul>\n        <li><strong>Fibroscan کبد</strong> + آزمایش هپاتیت B/C (هزینه ≈ ۵ میلیون تومان)</li>\n        <li><strong>آزمایش ژنتیک CYP1A2</strong> (اختیاری): اگر بیمار مصرف‌کننده قهوه/سیگار است، متابولیسم کلوزاپین تحت تأثیر قرار می‌گیرد</li>\n        <li>در سطح ۴: اگر آزمایشگاه در دسترس نیست، از <strong>والپروات با دوز پایین</strong> شروع کنید</li>\n      </ul>\n    </div>\n\n    <div class=\"sub-block\">\n      <h3 class=\"sub-title\">مداخلات روانی-اجتماعی مبتنی بر شواهد</h3>\n      <div class=\"cards-grid cards-grid-3\">\n        <div class=\"psych\"><h4>مصاحبه انگیزشی (MI)</h4><p>افزایش انگیزه برای ترک و پایبندی</p><span class=\"meta\">۴-۶ جلسه · NICE CG120 — سطح A</span></div>\n        <div class=\"psych\"><h4>DBT یکپارچه</h4><p>تنظیم هیجان + تحمل پریشانی + اثربخشی بین‌فردی</p><span class=\"meta\">۶-۱۲ ماه · WADD-SEPD 2024</span></div>\n        <div class=\"psych\"><h4>CBT برای سایکوز</h4><p>شناسایی محرک‌های مصرف و علائم هشدار</p><span class=\"meta\">۱۲-۲۴ جلسه · Schizophrenia Bulletin 2024</span></div>\n        <div class=\"psych\"><h4>خانواده‌درمانی</h4><p>آموزش خانواده برای مدیریت بحران</p><span class=\"meta\">۶-۱۲ ماه · NICE NG58</span></div>\n        <div class=\"psych\"><h4>توانبخشی شناختی (CRT)</h4><p>بهبود کارکرد اجرایی (حافظه، توجه، برنامه‌ریزی)</p><span class=\"meta\">۳-۶ ماه · Canadian Guidelines</span></div>\n        <div class=\"psych\"><h4>EMDR (پس از تثبیت)</h4><p>پردازش ترومای کودکی و بین‌فردی</p><span class=\"meta\">۶-۱۲ جلسه · سطح B</span></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ===================== TREATMENT LEVELS ===================== -->\n<section id=\"levels\" class=\"section section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head\">\n      <span class=\"section-kicker\">۴ سطح</span>\n      <h2>سطوح درمانی</h2>\n      <p class=\"section-sub\">بر اساس بودجه و دسترسی جغرافیایی — هر سطح قابل اجرا در ایران</p>\n    </div>\n\n    <div class=\"level-tabs\">\n      <span class=\"level-tab\">سطح ۱: دولتی-شهری</span>\n      <span class=\"level-tab\">سطح ۲: نیمه‌خصوصی</span>\n      <span class=\"level-tab\">سطح ۳: خصوصی-مدیریت‌شده</span>\n      <span class=\"level-tab\">سطح ۴: همراه-محور / روستایی</span>\n    </div>\n\n    <div class=\"level-detail\">\n      <h3>سطح ۱: دولتی-شهری <span class=\"muted\">— بیمارستان‌های دولتی تهران (روزبه، سینا، کهریزک)</span></h3>\n      <p class=\"budget\"><strong>💰 بودجه:</strong> ۱۲۰-۲۲۰ میلیون تومان</p>\n\n      <h4 class=\"blk\">خروجی مورد انتظار:</h4>\n      <div class=\"outcomes\">\n        <span class=\"outcome\">✅ تثبیت حاد در ۱۴ روز</span>\n        <span class=\"outcome\">✅ پاکی نسبی از ماه ۳</span>\n        <span class=\"outcome\">✅ شروع DBT از ماه ۲</span>\n        <span class=\"outcome\">✅ اشتغال محدود از ماه ۱۲</span>\n      </div>\n\n      <h4 class=\"blk\">فازهای درمان</h4>\n      <div class=\"table-wrap\">\n        <table>\n          <thead><tr><th>فاز</th><th>مدت</th><th>جزئیات</th><th>هزینه</th><th>نقش همراه</th></tr></thead>\n          <tbody>\n            <tr><td>بستری حاد</td><td>۱۰-۱۴ روز</td><td>بیمارستان روزبه (بخش حاد)</td><td>۱۵-۲۵ میلیون</td><td>همراه در سالن انتظار (۲-۴ ساعت روزانه)</td></tr>\n            <tr><td>بازتوانی نیمه‌باز</td><td>ماه ۲-۵</td><td>کلینیک روزانه روزبه (۶ ساعت روزانه)</td><td>۸-۱۲ میلیون/ماه</td><td>همراه در جلسات خانواده‌درمانی شرکت می‌کند</td></tr>\n            <tr><td>سرپایی</td><td>ماه ۶-۱۸</td><td>کلینیک دانشگاهی (DBT + EMDR)</td><td>۵-۸ میلیون/ماه</td><td>همراه نظارت بر مصرف دارو و تکالیف DBT</td></tr>\n            <tr><td>پیگیری</td><td>ماه ۱۲-۲۴</td><td>مطب دولتی (ویزیت هر ۲ ماه)</td><td>۲-۳ میلیون/ماه</td><td>همراه ثبت علائم روزانه</td></tr>\n          </tbody>\n        </table>\n      </div>\n\n      <h4 class=\"blk\">⚠️ هزینه‌های پنهان همراه</h4>\n      <div class=\"hidden-costs\">\n        <div class=\"hc\"><span>از دست رفتن درآمد همراه</span><strong>۴۰-۶۰ میلیون</strong></div>\n        <div class=\"hc\"><span>حمل و نقل</span><strong>۱۵-۲۵ میلیون</strong></div>\n        <div class=\"hc\"><span>فرسودگی همراه</span><strong>۵-۱۰ میلیون</strong></div>\n      </div>\n    </div>\n\n    <div class=\"sub-block\">\n      <h3 class=\"sub-title\">شاخص‌های موفقیت (KPIs)</h3>\n      <div class=\"kpi-row\">\n        <div class=\"kpi\"><div class=\"kpi-val\">۸۰٪</div><div class=\"kpi-label\">ماه ۳: پاکی نسبی</div></div>\n        <div class=\"kpi\"><div class=\"kpi-val\">۶۰٪</div><div class=\"kpi-label\">ماه ۶: ثبات خلق</div></div>\n        <div class=\"kpi\"><div class=\"kpi-val\">۴۰٪</div><div class=\"kpi-label\">ماه ۹: مهارت DBT</div></div>\n        <div class=\"kpi\"><div class=\"kpi-val\">۲۰٪</div><div class=\"kpi-label\">ماه ۱۲: اشتغال</div></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ===================== CAREGIVER ===================== -->\n<section id=\"caregiver\" class=\"section\">\n  <div class=\"container\">\n    <div class=\"section-head\">\n      <span class=\"section-kicker\">خانواده‌محور</span>\n      <h2>پروتکل ویژه همراه (Caregiver)</h2>\n      <p class=\"section-sub\">آموزش، ادغام در تیم درمانی، و حمایت از فرسودگی</p>\n    </div>\n\n    <h3 class=\"sub-title\">آموزش همراه (سطح ۴ — روستایی/همراه-محور) <span class=\"muted\">۳ روز آموزش فشرده</span></h3>\n    <div class=\"cards-grid cards-grid-4\">\n      <div class=\"train\"><div class=\"t-emoji\">👁️</div><h4>شناسایی علائم حاد سایکوز</h4><p>توهم (شنیدن صداهای ناموجود)، هذیان (باورهای غیرواقعی)، بیقراری شدید، رفتار خطرناک</p></div>\n      <div class=\"train\"><div class=\"t-emoji\">💊</div><h4>مدیریت دارو</h4><p>جلوگیری از Cheeking (نگه داشتن دارو در دهان)، ثبت زمان مصرف، نظارت بر دوز</p></div>\n      <div class=\"train\"><div class=\"t-emoji\">🧠</div><h4>مهارت‌های DBT ساده</h4><p>تأیید (Validation)، TIPP برای بحران (دوش آب سرد، تمرین تنفس، راه رفتن سریع)</p></div>\n      <div class=\"train\"><div class=\"t-emoji\">🚨</div><h4>شناسایی عوارض خطرناک کلوزاپین</h4><p>تب + گلودرد + سفتی عضلات → فوراً به اورژانس (آگرانولوسیتوزیس)</p></div>\n    </div>\n    <p class=\"tool-note\">🔧 ابزار: تلفن همراه با اپلیکیشن تماس تصویری اضطراری با روانپزشک تهران</p>\n\n    <h3 class=\"sub-title\">ادغام همراه (سطح ۳ — خصوصی-مدیریت‌شده) <span class=\"muted\">همراه به عنوان کو-تراپیست</span></h3>\n    <div class=\"cards-grid cards-grid-4\">\n      <div class=\"integ\"><div class=\"i-emoji\">🌙</div><h4>شب‌ها</h4><p>مانیتورینگ خواب و علائم حیاتی. ثبت کیفیت خواب و بیداری‌های شبانه.</p></div>\n      <div class=\"integ\"><div class=\"i-emoji\">☀️</div><h4>روزها</h4><p>ثبت تکالیف DBT و برنامه روزانه. همراهی در فعالیت‌های ساختاریافته.</p></div>\n      <div class=\"integ\"><div class=\"i-emoji\">⚠️</div><h4>در بحران</h4><p>استفاده از مهارت TIPP تا رسیدن پزشک. تماس فوری با تیم اورژانس.</p></div>\n      <div class=\"integ\"><div class=\"i-emoji\">🫂</div><h4>حمایت از همراه</h4><p>جلسات هفتگی ۱ ساعته با روانشناس برای جلوگیری از فرسودگی همراه. حقِ همراه به مراقبت از خود.</p></div>\n    </div>\n\n    <div class=\"sub-block\">\n      <h3 class=\"sub-title\">پروتکل کاهش آسیب (Harm Reduction) — در صورت لغزش</h3>\n      <div class=\"cards-grid cards-grid-4\">\n        <div class=\"hr-card\"><h4>کاهش مصرف به جای پرهیز مطلق</h4><p>مثلاً کاهش مصرف حشیش از روزانه به هفته‌ای</p><span class=\"meta\">NICE CG120</span></div>\n        <div class=\"hr-card\"><h4>جایگزینی با مواد کم‌خطر</h4><p>جایگزینی الکل با بنزودیازپین‌های تجویزی</p><span class=\"meta\">WFSBP 2023</span></div>\n        <div class=\"hr-card\"><h4>آزمایش ادرار منظم</h4><p>پایش مصرف و تنظیم دارو بر اساس نتایج</p><span class=\"meta\">APA 2020</span></div>\n        <div class=\"hr-card\"><h4>گروه‌های NA/AA</h4><p>حمایت همتا برای پیشگیری از عود</p><span class=\"meta\">Cochrane 2023</span></div>\n      </div>\n    </div>\n\n    <div class=\"callout callout-care\">\n      <h4>🫂 حقِ همراه: مراقبت از خودتان مهم است</h4>\n      <p>فرسودگی همراه (Caregiver Burnout) شایع و خطرناک است. همراهی با بیمار روانی + معتاد یکی از سخت‌ترین کارهای دنیاست.</p>\n      <ul>\n        <li>جلسات هفتگی با روانشناس برای خودتان</li>\n        <li>گروه‌های حمایتی خانواده‌ها (NA خانواده)</li>\n        <li>حق به استراحت و تنهایی</li>\n        <li>تماس با اورژانس اجتماعی ۱۲۳</li>\n        <li>درخواست کمک از دیگر اعضای خانواده</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ===================== PATIENT SHEET ===================== -->\n<section id=\"sheet\" class=\"section section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head\">\n      <span class=\"section-kicker\">عملی‌ترین بخش</span>\n      <h2>برگه معرفی بیمار (برای پزشک)</h2>\n      <p class=\"section-sub\">یک صفحه کاربردی، مبتنی بر شواهد، برای دادن به پزشک واقعی</p>\n    </div>\n\n    <div class=\"print-btn-row\"><button class=\"btn btn-primary\" onclick=\"window.print()\">چاپ برگه</button></div>\n\n    <div class=\"sheet\" id=\"printable-sheet\">\n      <h3 class=\"sheet-title\">برگه معرفی بیمار <span class=\"muted\">— نسخه نهایی، مبتنی بر شواهد علمی</span></h3>\n\n      <h4>📋 شرح حال مختصر:</h4>\n      <p class=\"sheet-text\">مرد، ساکن تهران، سابقه‌ی حدود ۲۵ سال مصرف مواد، همراه با علائم روان‌پریشی فعال (توهم/هذیان)، نشانه‌های اختلال شخصیت مرزی (خودآسیب‌رسانی، بی‌ثباتی هیجانی)، و ADHD درمان‌نشده. خانواده حاضر به همکاری و همراهی کامل است.</p>\n\n      <h4>❓ سؤالات ما، دکتر:</h4>\n      <div class=\"qa\">\n        <div class=\"q\"><span class=\"qn\">۱</span><p>آیا رویکرد درمان یکپارچه‌ی تشخیص دوگانه (Integrated Dual Diagnosis) — مطابق راهنمای NICE CG120 — برای او مناسب است؟ یا باید مرحله‌ای پیش برویم؟</p></div>\n        <div class=\"q\"><span class=\"qn\">۲</span><p>اگر آنتی‌سایکوتیک نسل دوم پاسخ نداد، آیا کلوزاپین پیش از ECT گزینه است؟ APA 2020 و WFSBP 2015 برای موارد مقاوم و کاهش مصرف مواد توصیه کرده‌اند.</p></div>\n        <div class=\"q\"><span class=\"qn\">۳</span><p>یک همراهِ تمام‌وقت داریم — چطور بخشی از تیم درمان (خانواده‌درمانی/نظارت دارویی) باشیم؟ همراه آماده‌ی آموزش است.</p></div>\n        <div class=\"q\"><span class=\"qn\">۴</span><p>برای شروع چه آزمایش‌هایی لازم است؟ شنیده‌ایم آزمایش کبد (Fibroscan) و شمارش خون (CBC) مهم است.</p></div>\n      </div>\n\n      <h4>مراجع علمی:</h4>\n      <ul class=\"refs-list\">\n        <li>NICE CG120: Psychosis with coexisting substance misuse</li>\n        <li>APA Practice Guideline for Schizophrenia (2020)</li>\n        <li>WFSBP Guidelines, Hasan et al. (2015)</li>\n      </ul>\n\n      <div class=\"sheet-note\">\n        <p><strong>چرا این برگه مهم است:</strong> ذکرِ نامِ راهنماها (NICE, APA, WFSBP) یک کارِ ظریف می‌کند: به پزشک نشان می‌دهد خانواده <strong>آگاه و جدی</strong> است، بدون این‌که بخواهد به او دیکته کند. پزشکِ خوب از این استقبال می‌کند. این برگه، حاصلِ تمام بررسی‌هاست. کوتاه، واقعی، و قابلِ استفاده. بقیه‌اش را پزشک تصمیم می‌گیرد — نه این پروتکل، نه ما.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ===================== DECISION TREE ===================== -->\n<section id=\"decision\" class=\"section\">\n  <div class=\"container\">\n    <div class=\"section-head\">\n      <span class=\"section-kicker\">Interactive</span>\n      <h2>درخت تصمیم</h2>\n      <p class=\"section-sub\">با پاسخ به چند سؤال ساده، سطح درمانی مناسب را بیابید</p>\n    </div>\n\n    <h3 class=\"sub-title\">بیمار کجا ساکن است؟ <span class=\"muted\">اولین سؤال: دسترسی جغرافیایی</span></h3>\n    <div class=\"decision-options\">\n      <button class=\"dec-opt\">تهران یا مرکز استان</button>\n      <button class=\"dec-opt\">شهرستان / روستا</button>\n    </div>\n\n    <h3 class=\"sub-title\">نمای کلی درخت تصمیم</h3>\n    <div class=\"tree\">\n      <div class=\"tree-node tree-q\">بیمار تهران ساکن است؟</div>\n      <div class=\"tree-branches\">\n        <div class=\"branch\">\n          <span class=\"branch-label\">✅ بله</span>\n          <div class=\"tree-node tree-q\">بودجه &gt; ۸۰۰ میلیون؟</div>\n          <div class=\"tree-branches\">\n            <div class=\"branch\"><span class=\"branch-label\">بله</span><span class=\"tree-result\">سطح ۳ (خصوصی)</span></div>\n            <div class=\"branch\"><span class=\"branch-label\">خیر</span><span class=\"tree-result\">سطح ۱ یا ۲</span></div>\n          </div>\n        </div>\n        <div class=\"branch\">\n          <span class=\"branch-label\">❌ خیر</span>\n          <div class=\"tree-node tree-q\">CBC هفتگی ممکن؟</div>\n          <div class=\"tree-branches\">\n            <div class=\"branch\"><span class=\"branch-label\">بله</span><span class=\"tree-result\">سطح ۱ (سفر ماهانه)</span></div>\n            <div class=\"branch\"><span class=\"branch-label\">خیر</span><span class=\"tree-result\">سطح ۴ (LAI + تله‌مدیسین)</span></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ===================== ACTION PLAN ===================== -->\n<section id=\"action\" class=\"section section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head\">\n      <span class=\"section-kicker\">اقدام عملی</span>\n      <h2>برنامه اجرایی فوری</h2>\n      <p class=\"section-sub\">قدم‌هایی که الان می‌توانید بردارید — از امروز تا ماه اول</p>\n    </div>\n\n    <div class=\"timeline\">\n      <div class=\"tl-col\">\n        <h3>امروز</h3>\n        <div class=\"tl-step\"><span class=\"tl-n\">۱</span><div><h4>وضعیت بیمار را ارزیابی کنید</h4><p>تهران‌نشین است یا شهرستان؟ بودجه واقعی خانواده؟ امکان همراه ۲۴ ساعته؟</p></div></div>\n        <div class=\"tl-step\"><span class=\"tl-n\">۲</span><div><h4>غربالگری کبد و آزمایش‌های پایه</h4><p>Fibroscan کبد + هپاتیت B/C + CBC + شیمی کامل + ادرار</p></div></div>\n        <div class=\"tl-step\"><span class=\"tl-n\">۳</span><div><h4>با نزدیک‌ترین روانپزشک تماس بگیرید</h4><p>سامانه نظام پزشکی: ۱۴۹۰ | اورژانس اجتماعی بهزیستی: ۱۲۳</p></div></div>\n      </div>\n      <div class=\"tl-col\">\n        <h3>هفته اول</h3>\n        <div class=\"tl-step\"><span class=\"tl-n\">۱</span><div><h4>نوبت ویزیت فوری بگیرید</h4><p>روانپزشک + روانشناس (ترجیحاً با تجربه Dual Diagnosis)</p></div></div>\n        <div class=\"tl-step\"><span class=\"tl-n\">۲</span><div><h4>همراه بیمار را برای آموزش آماده کنید</h4><p>آموزش اولیه: شناسایی علائم هشدار، مدیریت بحران</p></div></div>\n        <div class=\"tl-step\"><span class=\"tl-n\">۳</span><div><h4>برگه معرفی بیمار (بخش قبل) را به پزشک بدهید</h4><p>این برگه نشان می‌دهد خانواده آگاه و جدی است</p></div></div>\n      </div>\n      <div class=\"tl-col\">\n        <h3>ماه اول</h3>\n        <div class=\"tl-step\"><span class=\"tl-n\">۱</span><div><h4>بیمار را در برنامه ساختاریافته قرار دهید</h4><p>بستری، سرپایی یا خانگی — بسته به سطح درمانی انتخاب‌شده</p></div></div>\n        <div class=\"tl-step\"><span class=\"tl-n\">۲</span><div><h4>جلسات DBT را شروع کنید</h4><p>حضوری (تهران) یا آنلاین (شهرستان) — ۲ جلسه در هفته</p></div></div>\n        <div class=\"tl-step\"><span class=\"tl-n\">۳</span><div><h4>خانواده‌درمانی را آغاز کنید</h4><p>حداقل ۱ جلسه در هفته — همراه در جلسات شرکت می‌کند</p></div></div>\n        <div class=\"tl-step\"><span class=\"tl-n\">۴</span><div><h4>نظارت بر مصرف دارو برقرار شود</h4><p>همراه ثبت مصرف روزانه، عوارض، و علائم</p></div></div>\n      </div>\n    </div>\n\n    <div class=\"sub-block\">\n      <h3 class=\"sub-title\">توصیه بر اساس بودجه</h3>\n      <div class=\"cards-grid cards-grid-3\">\n        <div class=\"budget-card b-low\"><span class=\"b-tag\">🏘️ زیر ۱۰۰ میلیون تومان</span><h4>سطح ۴ (همراه-محور)</h4><p>همراه را آموزش دهید و از تله‌مدیسین و اورژانس اجتماعی ۱۲۳ استفاده کنید</p></div>\n        <div class=\"budget-card b-mid\"><span class=\"b-tag\">🏥 ۲۰۰-۷۰۰ میلیون تومان</span><h4>سطح ۱ یا ۲ (دولتی/نیمه‌خصوصی)</h4><p>بیمار را در تهران یا مرکز استان بستری کنید. از بیمه تکمیلی استفاده کنید</p></div>\n        <div class=\"budget-card b-high\"><span class=\"b-tag\">👑 بالای ۱ میلیارد تومان</span><h4>سطح ۳ (خصوصی-مدیریت‌شده)</h4><p>مدیریت پرونده تخصصی + همراه ۲۴ ساعته + ویلای درمانی</p></div>\n      </div>\n    </div>\n\n    <div class=\"sub-block\">\n      <h3 class=\"sub-title\">تماس‌های مهم</h3>\n      <div class=\"contacts\">\n        <a class=\"contact\" href=\"tel:123\"><span class=\"c-num\">۱۲۳</span><span class=\"c-name\">اورژانس روان<br><small>بهزیستی — ۲۴ ساعته</small></span></a>\n        <a class=\"contact\" href=\"tel:115\"><span class=\"c-num\">۱۱۵</span><span class=\"c-name\">اورژانس پزشکی<br><small>بحران حاد جسمانی</small></span></a>\n        <a class=\"contact\" href=\"tel:1490\"><span class=\"c-num\">۱۴۹۰</span><span class=\"c-name\">نظام پزشکی<br><small>پیدا کردن روانپزشک</small></span></a>\n        <a class=\"contact\" href=\"tel:1480\"><span class=\"c-num\">۱۴۸۰</span><span class=\"c-name\">خط خودکشی<br><small>مشاوره بحران</small></span></a>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ===================== REFERENCES ===================== -->\n<section id=\"references\" class=\"section\">\n  <div class=\"container\">\n    <div class=\"section-head\">\n      <span class=\"section-kicker\">References</span>\n      <h2>منابع و مراجع علمی</h2>\n      <p class=\"section-sub\">مقالات کلیدی، راهنماها، و کتاب‌های پیشنهادی</p>\n    </div>\n\n    <div class=\"cards-grid cards-grid-3\">\n      <div class=\"ref-group\">\n        <h3>راهنماها (Guidelines)</h3>\n        <div class=\"ref\"><span class=\"ref-year\">۲۰۱۱+</span><h4>NICE CG120</h4><p>Psychosis with coexisting substance misuse</p></div>\n        <div class=\"ref\"><span class=\"ref-year\">۲۰۱۶</span><h4>NICE NG58</h4><p>Coexisting severe mental illness and substance misuse</p></div>\n        <div class=\"ref\"><span class=\"ref-year\">۲۰۲۰</span><h4>APA Practice Guideline</h4><p>Treatment of Patients With Schizophrenia</p></div>\n        <div class=\"ref\"><span class=\"ref-year\">۲۰۱۵/۲۰۲۳</span><h4>WFSBP Guidelines</h4><p>Hasan et al. — Schizophrenia + SUD</p></div>\n        <div class=\"ref\"><span class=\"ref-year\">۲۰۲۳</span><h4>Canadian Schizophrenia Guidelines</h4><p>Integrated treatment in Early Intervention</p></div>\n      </div>\n\n      <div class=\"ref-group\">\n        <h3>مقالات مروری و متاآنالیز</h3>\n        <div class=\"ref\"><span class=\"ref-type\">Systematic Review &amp; Meta-analysis · ۲۰۲۳</span><h4>Effects of clozapine on substance use disorders in schizophrenia</h4><p>شواهد مثبت برای پرهیز و کاهش بستری</p></div>\n        <div class=\"ref\"><span class=\"ref-type\">Schizophrenia Bulletin · ۲۰۲۴</span><h4>Psychosocial Interventions for Individuals With Comorbid Psychosis and SUD</h4><p>متاآنالیز مداخلات روانی-اجتماعی</p></div>\n        <div class=\"ref\"><span class=\"ref-type\">Consensus Statement · ۲۰۲۴-۲۰۲۵</span><h4>WADD-SEPD Consensus on Psychological Treatment of Dual Disorders</h4><p>توصیه‌های مبتنی بر اجماع بین‌المللی</p></div>\n        <div class=\"ref\"><span class=\"ref-type\">Annals of General Psychiatry · ۲۰۲۴</span><h4>Management of schizophrenia and comorbid SUD: expert review</h4><p>مرور کارشناسانه و راهنمای عملی</p></div>\n        <div class=\"ref\"><span class=\"ref-type\">Classic Review · Mueser et al.</span><h4>Dual diagnosis: A review of etiological theories</h4><p>مرور کلاسیک مدل‌های اتیولوژیکی</p></div>\n        <div class=\"ref\"><span class=\"ref-type\">ScienceDirect · ۲۰۲۳</span><h4>Substance use disorders in schizophrenia: Prevalence, etiology, biomarkers</h4><p>بررسی جامع زیست‌نشانگ‌ها و اتیولوژی</p></div>\n      </div>\n\n      <div class=\"ref-group\">\n        <h3>کتاب‌های پیشنهادی</h3>\n        <div class=\"ref\"><span class=\"ref-year\">۲۰۲۳</span><h4>Integrated Treatment for Dual Disorders</h4><p>Mueser et al. — مرجع جامع درمان یکپارچه تشخیص دوگانه</p></div>\n        <div class=\"ref\"><span class=\"ref-year\">۲۰۲۴</span><h4>DBT for Complex PTSD</h4><p>Chapman — فصل ۱۰: کاربرد در سایکوز + BPD</p></div>\n        <div class=\"ref\"><span class=\"ref-year\">۲۰۲۳</span><h4>Substance Use Disorders in Schizophrenia</h4><p>Thompson et al. — اپیدمیولوژی، زیست‌نشانگ‌ها و درمان</p></div>\n      </div>\n    </div>\n\n    <div class=\"callout callout-iran\">\n      <h4>🇮🇷 شرایط ایران</h4>\n      <p>پروتکل‌های رسمی داخلی بیشتر روی اعتیاد متمرکزند و پوشش تشخیص دوگانه هنوز محدود است. بنابراین <strong>تطبیق راهنماهای NICE/APA/WFSBP با امکانات محلی</strong> ضروری است. ابزارهای تطبیقی: مراکز روزبه و رازی (تهران)، تله‌مدیسین (شهرستان‌ها)، همراه آموزش‌دیده (روستا)، اورژانس اجتماعی ۱۲۳ و پزشک خانواده روستایی.</p>\n    </div>\n  </div>\n</section>\n\n<!-- ===================== FOOTER ===================== -->\n<footer class=\"site-footer\">\n  <div class=\"container\">\n    <p><strong>پروتکل درمان تشخیص دوگانه برای ایران</strong></p>\n    <p class=\"footer-sub\">سایکوز / اسکیزوفرنی + اختلال مصرف مواد + BPD ± ADHD — مبتنی بر شواهد علمی NICE · APA · WFSBP</p>\n    <p class=\"footer-sub\">\n      🤖 دستیار هوشمند همین پروتکل در تلگرام:\n      <a href=\"https://t.me/AI_Aiddiction_Assistant_bot\" target=\"_blank\" rel=\"noopener\">@AI_Aiddiction_Assistant_bot</a>\n       ·\n      📚 موتور پرسش‌وپاسخ (RAG):\n      <a href=\"https://github.com/SBZ-EDU/dual-diagnosis-rag\" target=\"_blank\" rel=\"noopener\">dual-diagnosis-rag</a>\n    </p>\n    <p class=\"footer-warn\">⚠️ این پروتکل جایگزین مشاوره پزشک نیست. تصمیم نهایی درمان همیشه با پزشک معالج است.</p>\n  </div>\n</footer>\n\n<script>\n(function () {\n  var API = \"/api/chat\"; // نسبی: همان مبدأ ورکر\n  var DISCLAIMER = \"\\n\\n⚠️ این پاسخ جایگزین مشاوره پزشک نیست.\";\n  var btn = document.createElement(\"button\");\n  btn.id = \"ddx-chat-btn\"; btn.type = \"button\"; btn.textContent = \"💬 پرسش از دستیار\";\n  var panel = document.createElement(\"div\"); panel.id = \"ddx-chat-panel\";\n  panel.innerHTML = '<div id=\"ddx-chat-head\"><b>دستیار تشخیص دوگانه</b>' +\n    '<button id=\"ddx-chat-close\" type=\"button\" aria-label=\"بستن\">×</button></div>' +\n    '<div id=\"ddx-chat-msgs\"></div>' +\n    '<form id=\"ddx-chat-form\"><input id=\"ddx-chat-in\" placeholder=\"سؤال خود را فارسی بنویسید…\" ' +\n    'autocomplete=\"off\" maxlength=\"500\"><button id=\"ddx-chat-send\" type=\"submit\">ارسال</button></form>';\n  document.body.appendChild(btn); document.body.appendChild(panel);\n  var msgs = panel.querySelector(\"#ddx-chat-msgs\");\n  function add(text, who) {\n    var d = document.createElement(\"div\"); d.className = \"ddx-msg \" + who;\n    d.textContent = text; msgs.appendChild(d); msgs.scrollTop = msgs.scrollHeight; return d;\n  }\n  add(\"سلام! سؤال بالینی خود را درباره‌ی تشخیص دوگانه بپرسید؛ پاسخ فارسی و با ذکر منابع علمی داده می‌شود.\", \"bot\");\n  btn.onclick = function () { panel.classList.toggle(\"open\");\n    if (panel.classList.contains(\"open\")) panel.querySelector(\"#ddx-chat-in\").focus(); };\n  panel.querySelector(\"#ddx-chat-close\").onclick = function () { panel.classList.remove(\"open\"); };\n  panel.querySelector(\"#ddx-chat-form\").onsubmit = function (e) {\n    e.preventDefault();\n    var inp = panel.querySelector(\"#ddx-chat-in\"), q = inp.value.trim();\n    if (!q) return; inp.value = \"\";\n    add(q, \"user\");\n    var busy = add(\"در حال پاسخ‌گویی…\", \"bot\");\n    panel.querySelector(\"#ddx-chat-send\").disabled = true;\n    fetch(API, { method: \"POST\", headers: { \"content-type\": \"application/json\" },\n      body: JSON.stringify({ question: q, role: \"patient\" }) })\n      .then(function (r) { return r.json(); })\n      .then(function (d) {\n        busy.textContent = (d.answer || d.error || \"پاسخی دریافت نشد.\") +\n          (d.answer ? DISCLAIMER : \"\");\n        msgs.scrollTop = msgs.scrollHeight;\n      })\n      .catch(function () {\n        busy.textContent = \"خطای ارتباط با دستیار. اتصال اینترنت را بررسی و دوباره تلاش کنید.\";\n      })\n      .finally(function () { panel.querySelector(\"#ddx-chat-send\").disabled = false; });\n  };\n})();\n</script>\n</body>\n</html>\n";
